const AUTO_REPLIES = [
  (me: string, s: string) => `Thanks ${me} — got it. I'll go through "${s}" this afternoon and circle back if anything's unclear.`,
  (me: string) => `Perfect, this is exactly what I needed. Appreciate the quick turnaround, ${me}!`,
