          threads[threadId] = {
            ...existing,
            messages: [...existing.messages, message],
            unread: true,
            inInbox: existing.muted ? existing.inInbox : true,
            trashed: false,
            spam: false,
            snoozedUntil: null,
          };
        } else {
          threads[threadId] = {
            id: threadId,
            subject: inc.subject,
            messages: [message],
            category: inc.category,
            labels: inc.labels ?? [],
            unread: true,
            starred: false,
            important: inc.important ?? false,
            inInbox: true,
            trashed: false,
            spam: false,
            snoozedUntil: null,
          };
        }
