const LEAVES_VIEW: BulkAction[] = ['archive', 'trash', 'deleteForever', 'spam', 'notSpam', 'mute', 'inbox', 'unsnooze'];

export function runAction(ids: string[], action: BulkAction) {
  if (!ids.length) return;
  const mail = useMail.getState();
  const n = ids.length;
